css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; }
.loader::after { content: ''; position: absolute; bottom: 4%; left: 0; width: 100%; height: 15%; border-radius: 4px; background: linear-gradient(90deg, var(--accent-2) 0 50%, color-mix(in srgb, #fff 42%, var(--accent-2)) 50% 100%); background-size: calc(var(--loader-size) * .24) 100%; animation: current calc(var(--loader-speed) * 1.2) linear infinite; }
.loader .wheel { position: relative; width: 66%; height: 66%; border-radius: 50%; box-shadow: 0 0 0 calc(var(--loader-size) * .035) var(--accent); animation: churn calc(var(--loader-speed) * 3) linear infinite; }
.loader .wheel span { position: absolute; top: 50%; left: 50%; width: 46%; height: 11%; margin-top: -5.5%; border-radius: 2px; transform-origin: left center; background: linear-gradient(90deg, color-mix(in srgb, #000 22%, var(--accent-2)), var(--accent-2)); }
.loader .wheel span:nth-child(2) { transform: rotate(60deg); }
.loader .wheel span:nth-child(3) { transform: rotate(120deg); }
.loader .wheel span:nth-child(4) { transform: rotate(180deg); }
.loader .wheel span:nth-child(5) { transform: rotate(240deg); }
.loader .wheel span:nth-child(6) { transform: rotate(300deg); }
@keyframes churn { to { transform: rotate(360deg); } }
@keyframes current { to { background-position: calc(var(--loader-size) * .24) 0; } }
